/* @lc app=leetcode id=3937 lang=kotlin */ class Solution { fun minOperations(nums: IntArray, k: Int): Int = (0 until k).map { x -> nums.indices.filter { it % 2 == 0 }.sumOf { i -> (Math.abs(nums[i] % k - x)).let { minOf(it, k - it) } } }.let { ce -> (0 until k).map { y -> nums.indices.filter { it % 2 == 1 }.sumOf { i -> (Math.abs(nums[i] % k - y)).let { minOf(it, k - it) } } }.let { co -> (0 until k).flatMap { x -> (0 until k).filter { it != x }.map { y -> ce[x] + co[y] } }.min() } } }